from pathlib import Path
import subprocess,json,statistics,hashlib
r=Path.cwd();d=r/'build/hot-code-audit';old=r.parent/'profile-guided-pipeline/build/hot-code-audit'
def run(args):return subprocess.run(list(map(str,args)),capture_output=True,text=True,check=True)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert sha(d/'kernel.o')!=sha(old/'kernel.o')
assert sha(r/'benchmarks/compiler-gaps/symbol-materialization.coil')==sha(old/'generator.coil')
run(['cc','-O3','-c',d/'runner.c','-o',d/'runner.o']);rows=[]
for name,obj in [('before',old/'kernel.o'),('latest',d/'kernel.o')]:
 run(['cc',d/'runner.o',obj,'-o',d/name]);(d/(name+'.asm')).write_text(run(['llvm-objdump','-dr','--no-show-raw-insn',obj]).stdout);rows.append(dict(name=name,object_sha256=sha(obj),object_bytes=obj.stat().st_size,cpu_ns=[]))
for turn in range(9):
 for row in rows[turn%2:]+rows[:turn%2]:
  answer=int(run([d/row['name']]).stdout)
  if turn:row['cpu_ns'].append(answer)
for row in rows:row['median_ns']=statistics.median(row['cpu_ns']);print(row['name'],row['median_ns']/1e6,flush=True)
(d/'results.json').write_text(json.dumps(dict(qualification='4x1M loop iterations with16 conditional symbol stores. O3 images generated by identical Coil fixture against distinct local library roots. Same independent C caller, all49 small/wrapping-selector cases checked before timing;8 alternating CPU samples after warmup. Not a bootstrap result.',runner_sha256=sha(d/'runner.o'),generator_sha256=sha(r/'benchmarks/compiler-gaps/symbol-materialization.coil'),placement_sha256=sha(r/'src/stogir/placement.coil'),before_placement_sha256=sha(r.parent/'profile-guided-pipeline/src/stogir/placement.coil'),rows=rows),indent=2))
